const $=id=>document.getElementById(id),app=$('app');
app.dataset.mode='game-development';
let gameAddon=null,gameOverlayOpen=false,shoulderCamera=null,cameraAvatarOpacity=1;
const store={get(key,fallback){try{return JSON.parse(localStorage.getItem('tswg:walk:'+key))??fallback}catch{return fallback}},set(key,value){try{localStorage.setItem('tswg:walk:'+key,JSON.stringify(value))}catch{}}};
const prefs={quality:'auto',speed:2.8,sensitivity:3,bobbing:false,movementMode:'walk',runSpeed:6,...store.get('settings',{})};
let distance=store.get('distance',0),visited=new Set(store.get('visited',[]).filter(id=>ZONES.some(z=>z.id===id)));
let started=false,activePanel=null,activeSpot=null,panelTrigger=null,toastTimer,renderer,station,camera;
