let audioContext,audioGain,noiseSource,footstepTimer=0;

function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3900)}
function save(){store.set('distance',Math.round(distance));store.set('visited',[...visited]);store.set('settings',prefs)}
function updateStats(){$('distance').textContent=Math.floor(distance);$('visited-count').textContent=visited.size;$('total-count').textContent=ZONES.length}
function start(){if(started)return;started=true;app.classList.add('started');$('welcome').hidden=true;toast('左のスティックで歩く・画面をなぞって見回す');markVisited('dome')}
function markVisited(id){if(visited.has(id))return;visited.add(id);updateStats();save();document.querySelector(`.hotspot[data-id="${id}"]`)?.classList.add('visited');document.querySelector(`.spot-list [data-jump="${id}"]`)?.classList.add('visited')}
function clearInputs(){keyState.clear();joy.x=joy.y=0;joy.id=null;$('joy-knob').style.transform='';drag=null;walking=false}
function closePanels(){const previous=panelTrigger;document.querySelectorAll('.panel').forEach(p=>p.hidden=true);$('scrim').hidden=true;activePanel=null;panelTrigger=null;if(previous?.isConnected)previous.focus();updateNav()}
function updateNav(){document.querySelectorAll('.bottom-nav button').forEach(b=>b.classList.toggle('active',activePanel?b.dataset.panel===activePanel:b.id===(tour?'guided-walk':'free-walk')))}
function openPanel(id){gameAddon?.close();closeSpot();clearInputs();closePanels();panelTrigger=document.activeElement;activePanel=id;const panel=$('panel-'+id);panel.hidden=false;panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');$('scrim').hidden=false;if(id==='map'){selectedGuidePlace=null;$('guide-detail').hidden=true;setGuideMode('map');setMapFloor(currentFloor)}updateNav();panel.querySelector('.close-panel').focus()}
function closeSpot(){$('spot-card').hidden=true;activeSpot=null}
function openSpot(id){gameAddon?.close();const spot=station.hotspots.find(s=>s.id===id);if(!spot)return;start();stopTour(false);closePanels();clearInputs();activeSpot=spot;$('spot-title').textContent=spot.title;$('spot-subtitle').textContent=spot.kind==='landmark'?spot.subtitle:spot.floor+' / '+spot.subtitle;const service=TRAIN_SERVICES.find(s=>s.zoneId===id);$('spot-body').textContent=spot.body+(service?' '+service.label+'の'+service.model+'を参考にした停車車両を配置しています。編成と寸法は短縮し、車内への乗車はできません。':'');$('spot-card').style.setProperty('--spot-color',GROUPS[spot.group].color);$('spot-card').hidden=false;markVisited(id)}
function selectGroup(group,announce=true){
 if(group!=='all'&&!GROUPS[group])return;selectedGroup=group;station.setRouteGroup?.(group);
 document.querySelectorAll('[data-route]').forEach(b=>{const active=b.dataset.route===group;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active))});for(const map of maps)map.filter(group);filterSpotList();
 const notes={all:['階を選んで、駅を歩こう。','2F・M2F・1FからB5Fまで。京葉線と総武・横須賀線の地下エリアは別の場所です。'],east:['北陸新幹線は、JR東日本側へ。','1F 北・南のりかえ口 → M2F → 2F 20〜23番線。東北・山形・秋田・北海道・上越と共通です。'],tokaido:['東海道・山陽新幹線はこちら。','1F 中央・南のりかえ口 → M2F → 2F 14〜19番線。北陸新幹線などとは別です。'],keiyo:['京葉線は、南側の地下ホームへ。','1F南側 → B1F連絡通路・動く歩道 → B2F改札 → B3F中間階 → B4Fホーム。'],sobu:['総武・横須賀線は、丸の内側の地下へ。','B1F → B4F総武地下コンコース → B5Fホーム。同じB4Fの京葉線とは別エリアです。']};
 $('route-note-title').textContent=notes[group][0];$('route-note-body').textContent=notes[group][1];$('route-note').dataset.group=group;if(tour)stopTour(false);if(announce)toast(group==='all'?'すべての路線を表示しています':GROUPS[group].label+'を表示しています');
}
function stopTour(announce=true){if(!tour)return;tour=null;$('tour-status').hidden=true;updateNav();if(announce)toast('ガイド散策を終了しました。自由に歩いてみましょう。')}
function manualInput(){if(tour)stopTour(false);lookTarget=null}
function fadeJump(zone){clearTimeout(jumpTimer);floorTravel=null;app.classList.remove('changing-floor');$('floor-transit').hidden=true;for(const select of document.querySelectorAll('[data-floor-select]'))select.disabled=false;lastConnectorId=null;app.classList.remove('transition-fade');void app.offsetWidth;app.classList.add('transition-fade');jumpTimer=setTimeout(()=>{applyFloor(zone.floor);player.set(zone.x,floorById(zone.floor).elevation+1.65,zone.z);yaw=zone.yaw??0;pitch=zone.pitch??.08;lookTarget=null;markVisited(zone.id)},260);setTimeout(()=>app.classList.remove('transition-fade'),700)}
function jump(id){const zone=ZONES.find(z=>z.id===id);if(!zone)return;start();stopTour(false);closePanels();closeSpot();clearInputs();if(zone.group!=='general')selectGroup(zone.group,false);fadeJump(zone);toast(`${zone.floor} ${displayZone(zone)}へ移動しました`)}
function tourZones(){const ids=selectedGroup==='keiyo'?['keiyo-start','keiyo-passage','keiyo-concourse','keiyo-intermediate','keiyo-platform-12']:selectedGroup==='sobu'?['b1-concourse','sobu-concourse','sobu-platform-12']:selectedGroup==='east'?['jr-east-north','m2-east-north','platform-east-2021']:selectedGroup==='tokaido'?['tokaido-central','m2-tokaido-central','platform-tokaido-1415']:null;return ids?ids.map(id=>ZONES.find(z=>z.id===id)):ZONES.filter(z=>z.floor===currentFloor)}
function setTourStop(index,list=tour?.list??tourZones()){if(index>=list.length){stopTour(false);toast(`${list.length}スポットを巡りました。引き続き、自由な散策を。`);return}const zone=list[index],path=buildingRoute({x:player.x,z:player.z,floor:currentFloor},zone,allowed);if(!path.length){stopTour(false);toast('通路の中央へ少し移動してから、ガイド散策を始めてください。');return}tour={index,list,zone,path,waypoint:0,phase:'travel',hold:0,stuck:0};$('tour-count').textContent=`${String(index+1).padStart(2,'0')} / ${String(list.length).padStart(2,'0')}`;$('tour-title').textContent=`${zone.floor} ${displayZone(zone)}`;$('tour-status').hidden=false;updateNav()}
function startTour(){start();closePanels();closeSpot();clearInputs();setTourStop(0,tourZones());toast('表示中の路線に合わせて巡ります。自分で操作すると自由散策に戻ります。')}
function nearestAngle(a,b){return a+Math.atan2(Math.sin(b-a),Math.cos(b-a))}
function allowed(x,z,floor=currentFloor){if(!insideFloor(x,z,floor))return false;const radius=.27;return !(station.collidersByFloor[floor]??[]).some(c=>x>c.minX-radius&&x<c.maxX+radius&&z>c.minZ-radius&&z<c.maxZ+radius)}
function move(dx,dz,count=true){const beforeX=player.x,beforeZ=player.z,steps=Math.max(1,Math.ceil(Math.hypot(dx,dz)/.16));for(let i=0;i<steps;i++){if(allowed(player.x+dx/steps,player.z))player.x+=dx/steps;if(allowed(player.x,player.z+dz/steps))player.z+=dz/steps}const moved=Math.hypot(player.x-beforeX,player.z-beforeZ);if(count)distance+=moved;if(moved>.00001){for(const event of detectGateCrossings({x:beforeX,z:beforeZ},{x:player.x,z:player.z},currentFloor)){const now=performance.now();if(now-(gateToastTimes.get(event.gate.id)??-Infinity)<850)continue;gateToastTimes.set(event.gate.id,now);markVisited(event.gate.zoneId);toast(event.message);gateBeep()}}return moved}
function updateTour(dt){
 if(!tour||floorTravel)return;if(tour.phase==='travel'){
 const waypoint=tour.path[tour.waypoint];if(!waypoint){tour.phase='look';markVisited(tour.zone.id);return}
 if(waypoint.kind==='transfer'){beginFloorTravel(waypoint,()=>{if(tour)tour.waypoint++});return}
 const dx=waypoint.x-player.x,dz=waypoint.z-player.z,len=Math.hypot(dx,dz);if(len<.18){if(tour.waypoint<tour.path.length-1){tour.waypoint++;return}tour.phase='look';markVisited(tour.zone.id);toast(tour.zone.floor+' '+displayZone(tour.zone)+'に到着しました。')}else{const desired=Math.atan2(-dx,-dz);yaw=THREE.MathUtils.lerp(yaw,nearestAngle(yaw,desired),Math.min(1,dt*3));pitch=THREE.MathUtils.lerp(pitch,.06,Math.min(1,dt*2));const step=Math.min(len,movementSpeed()*dt),travelled=move(dx/len*step,dz/len*step);walking=travelled>.001;tour.stuck=travelled<step*.1?tour.stuck+dt:0;if(tour.stuck>2){stopTour(false);toast('通路の中央へ少し移動してから、ガイド散策を再開できます。')}return}}
 if(!tour)return;tour.hold+=dt;yaw=THREE.MathUtils.lerp(yaw,nearestAngle(yaw,tour.zone.yaw??0),Math.min(1,dt*1.5));pitch=THREE.MathUtils.lerp(pitch,tour.zone.id==='dome'?.75:tour.zone.pitch??.1,Math.min(1,dt));if(tour.hold>5)setTourStop(tour.index+1)
}
async function toggleAudio(force){const enabled=typeof force==='boolean'?force:$('sound').getAttribute('aria-pressed')!=='true';try{if(enabled){if(!audioContext){audioContext=new(window.AudioContext||window.webkitAudioContext)();audioGain=audioContext.createGain();audioGain.gain.value=.09;audioGain.connect(audioContext.destination);const buffer=audioContext.createBuffer(1,audioContext.sampleRate*3,audioContext.sampleRate),data=buffer.getChannelData(0);let last=0;for(let i=0;i<data.length;i++){last=(last+Math.random()*.04-.02)/1.02;data[i]=last*.8}noiseSource=audioContext.createBufferSource();noiseSource.buffer=buffer;noiseSource.loop=true;const filter=audioContext.createBiquadFilter();filter.type='lowpass';filter.frequency.value=550;noiseSource.connect(filter);filter.connect(audioGain);noiseSource.start()}await audioContext.resume()}else if(audioContext)await audioContext.suspend();$('sound').setAttribute('aria-pressed',String(enabled));$('sound').setAttribute('aria-label',enabled?'環境音をオフにする':'環境音をオンにする');$('audio-toggle').checked=enabled;toast(enabled?'環境音をオンにしました':'環境音をオフにしました')}catch{toast('このブラウザでは環境音を再生できません')}}
function stepSound(){if(!audioContext||audioContext.state!=='running')return;const oscillator=audioContext.createOscillator(),gain=audioContext.createGain();oscillator.type='triangle';oscillator.frequency.setValueAtTime(100,audioContext.currentTime);oscillator.frequency.exponentialRampToValueAtTime(45,audioContext.currentTime+.08);gain.gain.setValueAtTime(.02,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.0001,audioContext.currentTime+.12);oscillator.connect(gain);gain.connect(audioContext.destination);oscillator.start();oscillator.stop(audioContext.currentTime+.13)}
function applyQuality(){renderer.setPixelRatio(prefs.quality==='low'?1:prefs.quality==='high'?Math.min(devicePixelRatio,2):Math.min(devicePixelRatio,1.5));renderer.shadowMap.enabled=prefs.quality!=='low';renderer.setSize(innerWidth,innerHeight);station.scene.traverse(object=>{if(object.material)for(const mat of Array.isArray(object.material)?object.material:[object.material])mat.needsUpdate=true})}
function resize(){if(!renderer||!camera)return;camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)}
function makeHotspots(){station.hotspots.forEach((spot,index)=>{const button=document.createElement('button');button.className='hotspot'+(visited.has(spot.id)?' visited':'');button.dataset.id=spot.id;button.style.setProperty('--spot-color',GROUPS[spot.group].color);button.setAttribute('aria-label',displayZone(spot)+'の解説');const ring=document.createElement('span');ring.className='spot-ring';ring.textContent=String(index+1).padStart(2,'0');const label=document.createElement('span');label.className='spot-label';label.textContent=spot.title;const sub=document.createElement('small');sub.textContent=spot.group==='general'?'スポットをみる':GROUPS[spot.group].shortLabel;label.append(sub);button.append(ring,label);button.addEventListener('click',()=>openSpot(spot.id));$('hotspots').append(button);spot.button=button})}
function updateUI(){
 const point={x:player.x,z:player.z,floor:currentFloor},place=resolveLocation(point),zones=ZONES.filter(z=>z.floor===currentFloor),nearest=zones.reduce((a,b)=>Math.hypot(player.x-a.x,player.z-a.z)<Math.hypot(player.x-b.x,player.z-b.z)?a:b);
 $('location-name').textContent=place.title;$('area-name').textContent=place.areaLabel;$('area-name').dataset.group=place.group;$('current-floor').textContent=floorTravel?'↕':currentFloor;$('current-floor').title=floorTravel?`${floorTravel.fromFloor} → ${floorTravel.target.floor}`:currentFloor;$('current-plan-floor').textContent=currentFloor;
 $('guide-current-note').textContent=`現在地：${currentFloor} ${place.title}`;$('look-up').setAttribute('aria-label',pitch>.65?'正面を向く':'天井を見上げる');$('compass-needle').style.transform=`rotate(${yaw*180/Math.PI}deg)`;
 for(const map of maps)map.update(player.x,player.z,yaw,currentFloor);
 for(const spot of station.hotspots){const matches=selectedGroup==='all'||spot.group==='general'||spot.group===selectedGroup;if(spot.floor!==currentFloor){spot.button.hidden=true;continue}projected.copy(spot.position).project(camera);const dist=player.distanceTo(spot.position);const visible=projected.z<1&&projected.z>-1&&Math.abs(projected.x)<.88&&projected.y<.58&&projected.y>-.5&&dist<22&&!activePanel&&!activeSpot&&!gameOverlayOpen&&matches;spot.button.hidden=!visible;if(visible)spot.button.style.transform=`translate(-50%,-50%) translate(${(projected.x*.5+.5)*innerWidth}px,${(-projected.y*.5+.5)*innerHeight}px)`;if(started&&Math.hypot(player.x-spot.x,player.z-spot.z)<4)markVisited(spot.id)}
 updateStats();updateMovementUI();updateConnectorPrompt();app.dataset.zone=nearest.id;app.dataset.place=place.id;app.dataset.area=place.group;app.dataset.paid=String(place.paid);app.dataset.floor=currentFloor;
}
function frame(time){requestAnimationFrame(frame);if(hidden)return;const dt=Math.min((time-lastTime)/1000||.016,.05);lastTime=time;elapsed+=dt;persistTime+=dt;walking=false;
 if(floorTravel){updateFloorTravel(dt)}else if(started&&!activePanel&&!activeSpot&&!gameOverlayOpen){if(tour)updateTour(dt);else{let forward=-joy.y+(keyState.has('KeyW')||keyState.has('ArrowUp')?1:0)-(keyState.has('KeyS')||keyState.has('ArrowDown')?1:0),side=joy.x+(keyState.has('KeyD')||keyState.has('ArrowRight')?1:0)-(keyState.has('KeyA')||keyState.has('ArrowLeft')?1:0);const len=Math.hypot(forward,side);if(len>.04){if(len>1){forward/=len;side/=len}const speed=movementSpeed()*dt;walking=move((-Math.sin(yaw)*forward+Math.cos(yaw)*side)*speed,(-Math.cos(yaw)*forward-Math.sin(yaw)*side)*speed)>.001}const belt=walkwayVelocity(player.x,player.z,currentFloor);if(belt)move(0,belt*dt)}}
 if(lookTarget&&!floorTravel){yaw=THREE.MathUtils.lerp(yaw,nearestAngle(yaw,lookTarget.yaw),Math.min(1,dt*4));pitch=THREE.MathUtils.lerp(pitch,lookTarget.pitch,Math.min(1,dt*4));if(Math.abs(pitch-lookTarget.pitch)<.005)lookTarget=null}camera.position.copy(player);if(walking&&prefs.bobbing&&!reducedMotion)camera.position.y+=Math.sin(elapsed*(effectiveMovementMode()==='run'?13:9))*(effectiveMovementMode()==='run'?.045:.025);camera.rotation.set(pitch,yaw,0,'YXZ');const shoulderPose=shoulderCamera?.update({player,yaw,pitch,floor:currentFloor,dt,active:gameAddon?.shoulderView??false});cameraAvatarOpacity=shoulderPose?.avatarOpacity??1;if(walking){footstepTimer+=dt;if(footstepTimer>(effectiveMovementMode()==='run'?.30:.52)){stepSound();footstepTimer=0}}station.update(elapsed,dt);gateVisuals?.update(player,currentFloor,dt);gameAddon?.update(dt);renderer.render(station.scene,camera);if(time-lastSave>120){updateUI();lastSave=time}if(persistTime>30){save();persistTime=0}}
function setupInputs(){const canvas=renderer.domElement;canvas.addEventListener('pointerdown',event=>{if(activePanel||activeSpot||floorTravel||gameOverlayOpen||event.button!==0)return;manualInput();drag={id:event.pointerId,x:event.clientX,y:event.clientY};canvas.setPointerCapture(event.pointerId)});canvas.addEventListener('pointermove',event=>{if(drag?.id!==event.pointerId)return;const sensitivity=Number(prefs.sensitivity)*.0011;yaw-=(event.clientX-drag.x)*sensitivity;pitch=THREE.MathUtils.clamp(pitch-(event.clientY-drag.y)*sensitivity,-1.2,1.48);drag.x=event.clientX;drag.y=event.clientY});const endDrag=event=>{if(drag?.id===event.pointerId)drag=null};canvas.addEventListener('pointerup',endDrag);canvas.addEventListener('pointercancel',endDrag);canvas.addEventListener('lostpointercapture',endDrag);canvas.addEventListener('contextmenu',event=>event.preventDefault());const joystick=$('joystick');const joyMove=event=>{if(joy.id!==event.pointerId)return;if(floorTravel)return;const rect=joystick.getBoundingClientRect();let x=event.clientX-rect.left-rect.width/2,y=event.clientY-rect.top-rect.height/2;const max=rect.width*.31,length=Math.hypot(x,y);if(length>max){x=x/length*max;y=y/length*max}joy.x=x/max;joy.y=y/max;$('joy-knob').style.transform=`translate(${x}px,${y}px)`};joystick.addEventListener('pointerdown',event=>{event.preventDefault();if(gameOverlayOpen)return;manualInput();start();joy.id=event.pointerId;joystick.setPointerCapture(event.pointerId);joyMove(event)});joystick.addEventListener('pointermove',joyMove);const endJoy=event=>{if(joy.id!==event.pointerId)return;joy.id=null;joy.x=joy.y=0;$('joy-knob').style.transform=''};joystick.addEventListener('pointerup',endJoy);joystick.addEventListener('pointercancel',endJoy);joystick.addEventListener('lostpointercapture',endJoy);window.addEventListener('keydown',event=>{if(event.code==='KeyE'&&!activePanel&&!activeSpot&&!floorTravel&&!gameOverlayOpen&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)){const entry=availableConnectors()[0];if(entry){event.preventDefault();useConnector(entry)}return}if(event.key==='Escape'){gameAddon?.close();closePanels();closeSpot();clearInputs();return}if(event.key==='Tab'&&activePanel){const elements=[...$('panel-'+activePanel).querySelectorAll('button,a[href],input,select,[tabindex="0"]')].filter(e=>!e.disabled&&!e.closest('[hidden]')),first=elements[0],last=elements.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}return}if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)||activePanel||floorTravel||gameOverlayOpen)return;if(event.code==='ShiftLeft'||event.code==='ShiftRight'){keyState.add(event.code);updateMovementUI();return}if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowLeft','ArrowDown','ArrowRight'].includes(event.code)){event.preventDefault();start();manualInput();keyState.add(event.code)}});window.addEventListener('keyup',event=>{keyState.delete(event.code);if(event.code==='ShiftLeft'||event.code==='ShiftRight')updateMovementUI()});window.addEventListener('blur',clearInputs);document.addEventListener('visibilitychange',()=>{hidden=document.hidden;clearInputs();if(hidden){save();audioContext?.suspend()}else{lastTime=performance.now();if($('sound').getAttribute('aria-pressed')==='true')audioContext?.resume()}})}
function buildSpotList(){const list=$('spot-list');for(const group of Object.keys(GROUPS)){const heading=document.createElement('h3');heading.className='spot-section-title';heading.dataset.group=group;heading.textContent=GROUPS[group].label;list.append(heading);ZONES.filter(z=>z.group===group).forEach(zone=>{const i=ZONES.indexOf(zone),button=document.createElement('button');button.dataset.jump=zone.id;button.dataset.group=group;button.dataset.floor=zone.floor;button.style.setProperty('--spot-color',GROUPS[group].color);if(visited.has(zone.id))button.classList.add('visited');const number=document.createElement('span');number.textContent=String(i+1).padStart(2,'0');const text=document.createElement('div'),title=document.createElement('strong'),sub=document.createElement('small');title.textContent=zone.title;sub.textContent=zone.floor+'｜'+(zone.kind==='transfer'?`${GROUPS[group].operator}｜${GROUPS[group].platforms}`:zone.kind==='platform'?'ホームの散策':zone.group==='keiyo'?'京葉線・武蔵野線':zone.group==='sobu'?'総武快速線・横須賀線':zone.side==='west'?'丸の内方面':zone.side==='east'?'八重洲方面':floorById(zone.floor).title);text.append(title,sub);const arrow=document.createElement('span');arrow.className='spot-arrow';arrow.textContent='→';button.append(number,text,arrow);button.addEventListener('click',()=>selectGuideSpot(zone.id));list.append(button)})}}
function setupUI(){buildSpotList();maps=[buildMap($('main-station-map'),{onJump:selectGuideSpot,onSelectGate:selectGuideGate}),buildMap($('mini-station-map'),{mini:true})];$('start').addEventListener('click',start);document.querySelectorAll('[data-panel]').forEach(b=>b.addEventListener('click',()=>openPanel(b.dataset.panel)));document.querySelectorAll('.close-panel').forEach(b=>b.addEventListener('click',closePanels));$('scrim').addEventListener('click',closePanels);document.querySelectorAll('[data-route]').forEach(b=>b.addEventListener('click',()=>selectGroup(b.dataset.route)));$('free-walk').addEventListener('click',()=>{start();closePanels();closeSpot();stopTour(false)});$('guided-walk').addEventListener('click',startTour);$('tour-stop').addEventListener('click',()=>stopTour());$('tour-next').addEventListener('click',()=>{if(tour)setTourStop(tour.index+1)});$('home').addEventListener('click',()=>jump('dome'));$('look-up').addEventListener('click',()=>{start();manualInput();if(pitch>.65){lookTarget={yaw,pitch:.08};toast('視点を正面に戻しました')}else{if(currentFloor==='1F'&&player.x<-35&&Math.min(Math.abs(player.z-30),Math.abs(player.z+30))<15){const dz=(player.z>0?30:-30)-player.z,dx=-49-player.x;lookTarget={yaw:Math.atan2(-dx,-dz),pitch:1.35}}else lookTarget={yaw,pitch:.95};toast('もう一度押すと、視点を正面に戻せます')}});$('spot-close').addEventListener('click',closeSpot);$('spot-look').addEventListener('click',()=>{const spot=activeSpot;closeSpot();if(!spot)return;const delta=spot.position.clone().sub(player);lookTarget={yaw:Math.atan2(-delta.x,-delta.z),pitch:Math.atan2(delta.y,Math.hypot(delta.x,delta.z))}});$('photo').addEventListener('click',()=>{renderer.render(station.scene,camera);renderer.domElement.toBlob(blob=>{if(!blob){toast('写真を保存できませんでした');return}const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`tokyo-station-walk-${new Date().toISOString().slice(0,10)}.png`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('散策の風景を保存しました')},'image/png')});$('sound').addEventListener('click',()=>toggleAudio());$('audio-toggle').addEventListener('change',e=>toggleAudio(e.target.checked));for(const id of ['quality','speed','sensitivity','bobbing']){const el=$(id);if(id==='bobbing')el.checked=prefs[id];else el.value=String(prefs[id]);el.addEventListener('change',()=>{prefs[id]=id==='bobbing'?el.checked:el.value;if(id==='quality')applyQuality();save()})}$('reset-progress').addEventListener('click',()=>{distance=0;visited.clear();document.querySelectorAll('.hotspot,.spot-list button').forEach(b=>b.classList.remove('visited'));updateStats();save();toast('散策の記録をリセットしました')});selectGroup('all',false)}


function effectiveMovementMode(){return prefs.movementMode==='run'||keyState.has('ShiftLeft')||keyState.has('ShiftRight')?'run':'walk'}
function movementSpeed(){return Number(effectiveMovementMode()==='run'?prefs.runSpeed:prefs.speed)}
function updateMovementUI(){const mode=effectiveMovementMode();for(const button of document.querySelectorAll('[data-movement-mode]')){const selected=button.dataset.movementMode===mode;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected))}app.dataset.movementMode=mode}
function setMovementMode(mode){prefs.movementMode=mode==='run'?'run':'walk';updateMovementUI();save();toast(prefs.movementMode==='run'?'走るモードに切り替えました':'歩くモードに切り替えました')}
function setupMovementUI(){for(const button of document.querySelectorAll('[data-movement-mode]'))button.addEventListener('click',()=>setMovementMode(button.dataset.movementMode));$('run-speed').value=String(prefs.runSpeed);$('run-speed').addEventListener('change',event=>{prefs.runSpeed=Number(event.target.value);save()});updateMovementUI()}

function displayZone(zone){return zone.kind==='transfer'?zoneLabel(zone):zone.title}
function filterSpotList(){const floor=activePanel==='map'?mapViewFloor:currentFloor;for(const el of document.querySelectorAll('.spot-list button[data-jump]'))el.hidden=(floor!=='overview'&&el.dataset.floor!==floor)||(selectedGroup!=='all'&&el.dataset.group!=='general'&&el.dataset.group!==selectedGroup);for(const heading of document.querySelectorAll('.spot-section-title'))heading.hidden=![...document.querySelectorAll('.spot-list button')].some(b=>b.dataset.group===heading.dataset.group&&!b.hidden)}
function applyFloor(id){currentFloor=id;station.setFloor(id);for(const select of document.querySelectorAll('[data-floor-select]'))select.value=id;maps[1]?.update(player.x,player.z,yaw,id);setMapFloor(id);$('mini-floor-label').textContent=id;filterSpotList();connectorSignature='';app.dataset.floor=id}
function setupFloorUI(){$('connector-dismiss').addEventListener('click',()=>{dismissedPrompt={floor:currentFloor,x:player.x,z:player.z};$('connector-card').hidden=true;connectorSignature=''});for(const select of document.querySelectorAll('[data-floor-select]')){for(const floor of FLOORS){const option=document.createElement('option');option.value=floor.id;option.textContent=select.id==='floor-select'?floor.id:`${floor.id}｜${floor.title}`;select.append(option)}select.value=currentFloor;select.addEventListener('change',()=>{const id=select.value;const zone=ZONES.find(z=>z.floor===id&&z.group===selectedGroup)??ZONES.find(z=>z.id===floorById(id).defaultZone);if(selectedGroup!=='all'&&!ZONES.some(z=>z.floor===id&&z.group===selectedGroup))selectGroup('all',false);jump(zone.id)})}}
function beginFloorTravel(target,onDone){if(floorTravel)return;clearInputs();lookTarget=null;const destination=new THREE.Vector3(target.x,floorById(target.floor).elevation+1.65,target.z),area=FLOOR_AREAS[target.floor].find(a=>target.x>=a.minX&&target.x<=a.maxX&&target.z>=a.minZ&&target.z<=a.maxZ);const dx=(area.minX+area.maxX)/2-target.x,dz=(area.minZ+area.maxZ)/2-target.z,targetYaw=Math.hypot(dx,dz)>.1?Math.atan2(-dx,-dz):yaw;lastConnectorId=target.connectorId;floorTravel={targetYaw,fromFloor:currentFloor,from:player.clone(),destination,target,elapsed:0,duration:reducedMotion?.18:1.25,switched:false,onDone};$('floor-transit').hidden=false;$('floor-transit-label').textContent=`${currentFloor} → ${target.floor}`;$('connector-card').hidden=true;app.classList.add('changing-floor');for(const select of document.querySelectorAll('[data-floor-select]'))select.disabled=true}
function updateFloorTravel(dt){const motion=floorTravel;motion.elapsed+=dt;const t=Math.min(motion.elapsed/motion.duration,1),ease=t*t*(3-2*t);player.lerpVectors(motion.from,motion.destination,ease);yaw=THREE.MathUtils.lerp(yaw,nearestAngle(yaw,motion.targetYaw),Math.min(1,dt*5));if(t>.45&&!motion.switched){applyFloor(motion.target.floor);motion.switched=true}pitch=THREE.MathUtils.lerp(pitch,.08,Math.min(1,dt*4));$('floor-transit-progress').style.transform=`scaleX(${t})`;if(t>=1){player.copy(motion.destination);floorTravel=null;app.classList.remove('changing-floor');$('floor-transit').hidden=true;for(const select of document.querySelectorAll('[data-floor-select]'))select.disabled=false;motion.onDone?.();toast(motion.target.floor+' '+floorById(motion.target.floor).title+'へ移動しました。')}}
function useConnector(entry){if(floorTravel)return;start();stopTour(false);closeSpot();clearInputs();beginFloorTravel({...entry.to,connectorId:entry.connector.id},null)}
function availableConnectors(){if(dismissedPrompt){if(dismissedPrompt.floor===currentFloor&&Math.hypot(player.x-dismissedPrompt.x,player.z-dismissedPrompt.z)<4.2)return [];dismissedPrompt=null}if(lastConnectorId){const c=CONNECTORS.find(c=>c.id===lastConnectorId),p=c?.a.floor===currentFloor?c.a:c?.b.floor===currentFloor?c.b:null;if(!p||Math.hypot(player.x-p.x,player.z-p.z)>4.2)lastConnectorId=null}return nearestConnector(player,currentFloor).filter(e=>e.connector.id!==lastConnectorId)}
function updateConnectorPrompt(){const entries=started&&!activePanel&&!activeSpot&&!tour&&!floorTravel?availableConnectors():[];const signature=entries.map(e=>e.connector.id+e.to.floor).join('|');$('connector-card').hidden=!entries.length;if(signature===connectorSignature)return;connectorSignature=signature;const list=$('connector-options');list.replaceChildren();for(const entry of entries.slice(0,3)){const button=document.createElement('button');button.dataset.connector=entry.connector.id;button.className='connector-option';const up=floorById(entry.to.floor).elevation>floorById(currentFloor).elevation;const label=document.createElement('strong');label.textContent=`${up?'↑':'↓'} ${entry.to.floor}へ${up?'上がる':'下りる'}`;const sub=document.createElement('small');sub.textContent=entry.connector.kind==='elevator'?'エレベーター':entry.connector.title;button.append(label,sub);button.addEventListener('click',()=>useConnector(entry));list.append(button)}}


function openGuide(mode='map'){openPanel('map');setGuideMode(mode);if(mode==='gates')renderGateList()}
function setGuideMode(mode){guideMode=['map','gates','spots','trains','landmarks'].includes(mode)?mode:'map';for(const name of ['map','gates','spots','trains','landmarks']){$('guide-'+name+'-view').hidden=name!==guideMode;const tab=$('guide-'+name+'-tab');tab.setAttribute('aria-selected',String(name===guideMode));tab.tabIndex=name===guideMode?0:-1}if(guideMode==='gates')renderGateList();filterSpotList()}
function setMapFloor(id){if(id!=='overview'&&!floorById(id))return;mapViewFloor=id;maps[0]?.setViewFloor(id);for(const button of document.querySelectorAll('[data-map-floor]'))button.classList.toggle('selected',button.dataset.mapFloor===id);$('map-floor-select').value=id;$('floor-description').textContent=id==='overview'?'地上ホームから地下5階まで。階段の接続と、離れた京葉線エリアを見比べられます。':`${id} · ${floorById(id).description}`;filterSpotList()}
function showGuideDetail(place,type){selectedGuidePlace={place,type};const group=GROUPS[place.group];$('guide-detail-meta').textContent=type==='gate'?`${place.operator} / ${place.floor}`:`${group?.shortLabel??'東京駅'} / ${place.floor}`;$('guide-detail-title').textContent=place.title;$('guide-detail-destination').textContent=type==='gate'?place.destination:place.en;$('guide-detail-body').textContent=type==='gate'?(place.kind==='transfer'?'在来線の改札内と、こちらの新幹線の改札内を結ぶのりかえ口です。改札機の間はそのまま歩いて通れます。':'改札前から散策を始められます。改札機の間を歩くと、改札内・外の表示が切り替わります。'):place.body;const service=type==='spot'&&TRAIN_SERVICES.find(s=>s.zoneId===place.id);if(service){$('guide-detail-destination').textContent=service.label+' · '+service.model+'を参考にした車両';$('guide-detail-body').textContent=place.body+' 停車中の短縮編成をホームから眺められます。車内への乗車はできません。'}const landmark=type==='spot'&&place.kind==='landmark';$('guide-detail-source').hidden=!landmark;if(landmark){$('guide-detail-meta').textContent=place.floor+' / '+(place.paid?'改札内':'改札外');$('guide-detail-destination').textContent=place.side+' · 待ち合わせの目印';$('guide-detail-source').href=place.source}$('guide-detail').hidden=false}
function selectGuideGate(id){const gate=GATES.find(g=>g.id===id);if(!gate)return;setGuideMode('map');setMapFloor(gate.floor);maps[0].filter('all');maps[0].selectGate(gate.id);showGuideDetail(gate,'gate');$('panel-map').scrollTop=0}
function selectGuideSpot(id){const spot=ZONES.find(z=>z.id===id);if(!spot)return;setGuideMode('map');setMapFloor(spot.floor);maps[0].filter('all');maps[0].selectSpot(spot.id);showGuideDetail(spot,'spot');$('panel-map').scrollTop=0}
function walkFromGuide(){if(!selectedGuidePlace)return;const {place,type}=selectedGuidePlace;if(type==='spot'){const service=TRAIN_SERVICES.find(s=>s.zoneId===place.id);if(service){start();stopTour(false);closePanels();closeSpot();clearInputs();selectGroup(place.group==='general'?'all':place.group,false);fadeJump({...place,x:service.viewX,z:service.viewZ,yaw:service.viewYaw,pitch:.01});toast(place.title+'の電車を眺めながら散策できます。')}else{if(place.kind==='landmark')selectGroup('all',false);jump(place.id)}return}const original=ZONES.find(z=>z.id===place.zoneId),zone={...original,...place.spawn,floor:place.floor,group:place.group,pitch:.04,id:place.zoneId};start();stopTour(false);closePanels();closeSpot();clearInputs();selectGroup(place.group==='general'?'all':place.group,false);fadeJump(zone);toast(place.title+'の前から散策します。')}
function renderGateList(){const group=$('gate-operator').value,query=$('gate-search').value,gates=filterGates({group,query});$('gate-count').textContent=`${gates.length} か所`;$('gate-list').replaceChildren();const names={general:'JR東日本・在来線改札',east:'JR東日本・新幹線（北陸ほか）',tokaido:'JR東海・東海道・山陽新幹線',keiyo:'JR東日本・京葉地下改札'};for(const id of ['general','east','tokaido','keiyo']){const entries=gates.filter(g=>g.group===id);if(!entries.length)continue;const heading=document.createElement('h3');heading.className='gate-section-title';heading.textContent=names[id];heading.style.setProperty('--gate-color',gateColor(id));$('gate-list').append(heading);for(const gate of entries){const button=document.createElement('button');button.className='gate-row';button.dataset.gate=gate.id;button.style.setProperty('--gate-color',gateColor(id));const icon=document.createElement('span');icon.className='gate-symbol';icon.textContent='▥';const text=document.createElement('div'),title=document.createElement('strong'),sub=document.createElement('small'),arrow=document.createElement('span');title.textContent=gate.title;sub.textContent=`${gate.floor} · ${gate.destination}`;text.append(title,sub);arrow.className='gate-arrow';arrow.textContent='→';button.append(icon,text,arrow);button.addEventListener('click',()=>selectGuideGate(gate.id));$('gate-list').append(button)}}if(!gates.length){const empty=document.createElement('p');empty.className='gate-empty';empty.textContent='一致する改札がありません。路線や検索語を変えてみてください。';$('gate-list').append(empty)}}
function gateColor(group){return {general:'#51765b',east:'#4f8897',tokaido:'#b38252',keiyo:'#aa6b80'}[group]??'#6f8462'}
function buildLandmarkList(){
 const list=$('landmark-list');list.replaceChildren();
 for(const place of LANDMARKS){
  const button=document.createElement('button');button.type='button';button.className='landmark-row';button.dataset.landmark=place.id;
  const icon=document.createElement('span');icon.className='landmark-symbol';icon.setAttribute('aria-hidden','true');icon.textContent={bell:'鈴',wheel:'輪',square:'0',post:'〒'}[place.icon];
  const text=document.createElement('div'),title=document.createElement('strong'),meta=document.createElement('small'),access=document.createElement('span'),arrow=document.createElement('span');
  title.textContent=place.title;meta.textContent=place.floor+' · '+place.side;access.className='landmark-access';access.dataset.paid=String(place.paid);access.textContent=place.paid?'改札内':'改札外';text.append(title,meta,access);arrow.className='landmark-arrow';arrow.textContent='→';button.append(icon,text,arrow);
  button.addEventListener('click',()=>selectGuideSpot(place.id));list.append(button);
 }
}
function buildTrainList(){
 const list=$('train-list');list.replaceChildren();
 for(const floor of ['2F','B4F','B5F']){
  const entries=TRAIN_SERVICES.map(service=>({service,zone:ZONES.find(z=>z.id===service.zoneId)})).filter(entry=>entry.zone?.floor===floor);
  const heading=document.createElement('h3');heading.className='gate-section-title';heading.textContent=floor+' · '+floorById(floor).title;list.append(heading);
  for(const {service,zone} of entries){
   const button=document.createElement('button');button.type='button';button.className='train-row';button.dataset.trainZone=zone.id;button.style.setProperty('--train-color',service.color);
   const icon=document.createElement('span');icon.className='train-symbol';icon.setAttribute('aria-hidden','true');
   const svg=document.createElementNS('http://www.w3.org/2000/svg','svg'),use=document.createElementNS('http://www.w3.org/2000/svg','use');use.setAttribute('href','#i-train');svg.append(use);icon.append(svg);
   const text=document.createElement('div'),title=document.createElement('strong'),sub=document.createElement('small'),arrow=document.createElement('span');title.textContent=zone.title;sub.textContent=service.model+' · '+service.label;arrow.className='train-arrow';arrow.textContent='→';text.append(title,sub);button.append(icon,text,arrow);
   button.addEventListener('click',()=>selectGuideSpot(zone.id));list.append(button);
  }
 }
}
function setupGuideUI(){const guideTabs=[...document.querySelectorAll('[data-guide-mode]')];for(const button of guideTabs){button.addEventListener('click',()=>setGuideMode(button.dataset.guideMode));button.addEventListener('keydown',event=>{const index=guideTabs.indexOf(button);let next;if(event.key==='ArrowRight')next=(index+1)%guideTabs.length;else if(event.key==='ArrowLeft')next=(index-1+guideTabs.length)%guideTabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=guideTabs.length-1;else return;event.preventDefault();setGuideMode(guideTabs[next].dataset.guideMode);guideTabs[next].focus()})}const levels=[{id:'overview',title:'立体'},...FLOORS.map(f=>({id:f.id,title:f.id}))];for(const level of levels){const button=document.createElement('button');button.type='button';button.dataset.mapFloor=level.id;button.textContent=level.title;button.addEventListener('click',()=>{selectedGuidePlace=null;$('guide-detail').hidden=true;setMapFloor(level.id)});$('guide-floor-tabs').append(button);const option=document.createElement('option');option.value=level.id;option.textContent=level.title;$('map-floor-select').append(option)}$('map-floor-select').addEventListener('change',event=>setMapFloor(event.target.value));$('gate-operator').addEventListener('change',renderGateList);$('gate-search').addEventListener('input',renderGateList);$('guide-walk').addEventListener('click',walkFromGuide);$('map-zoom-in').addEventListener('click',()=>maps[0].zoom(1.35));$('map-zoom-out').addEventListener('click',()=>maps[0].zoom(1/1.35));$('map-locate').addEventListener('click',()=>{setMapFloor(currentFloor);maps[0].resetView()});$('guide-current-note').addEventListener('click',()=>{setMapFloor(currentFloor);maps[0].resetView()});$('current-plan').addEventListener('click',()=>openGuide('map'));$('play-gates').addEventListener('click',()=>openGuide('gates'));$('play-trains').addEventListener('click',()=>openGuide('trains'));$('play-landmarks').addEventListener('click',()=>openGuide('landmarks'));buildTrainList();buildLandmarkList();$('guide-gate-total').textContent=GATES.length;$('guide-spot-total').textContent=ZONES.length;renderGateList();setMapFloor(currentFloor)}
function gateBeep(){if(!audioContext||audioContext.state!=='running')return;const sound=audioContext.createOscillator(),gain=audioContext.createGain();sound.frequency.value=1050;gain.gain.setValueAtTime(.018,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.0001,audioContext.currentTime+.11);sound.connect(gain);gain.connect(audioContext.destination);sound.start();sound.stop(audioContext.currentTime+.12)}

function setupGameEdition(){
 gameAddon=createGameAddon({station,zones:ZONES,reducedMotion,
  getPlayer:()=>({x:player.x,y:player.y,z:player.z,floor:currentFloor,yaw,walking,movementMode:effectiveMovementMode()}),
  getCameraOpacity:()=>cameraAvatarOpacity,
  getLocation:()=>resolveLocation({x:player.x,z:player.z,floor:currentFloor}),
  openMap:()=>openPanel('map'),openSettings:()=>openPanel('settings'),openHelp:()=>openPanel('help'),
  project:({x,y,z})=>{const point=new THREE.Vector3(x,y,z).project(camera);return {x:(point.x*.5+.5)*innerWidth,y:(-.5*point.y+.5)*innerHeight,visible:point.z>-1&&point.z<1&&Math.abs(point.x)<.95&&Math.abs(point.y)<.95}},
  isStarted:()=>started,
  isActive:()=>started&&!activePanel&&!activeSpot&&!floorTravel&&!gameOverlayOpen,
  isAllowed:(x,z,floor)=>allowed(x,z,floor),
  onModalChange:open=>{gameOverlayOpen=open;clearInputs();if(open){stopTour(false);closePanels();closeSpot()}},
  jumpTo:id=>jump(id),onNotice:toast,
  guideTo:id=>{const zone=ZONES.find(z=>z.id===id);if(!zone)return;start();closePanels();closeSpot();clearInputs();setTourStop(0,[zone]);toast('目印まで歩いて案内します。自分で動くと案内を終了できます。');},
  originalUrl:'https://tokyo-station-walk-noriko.workspace-397612.chatgpt.site'
 });
}
async function init(){try{renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.domElement.setAttribute('aria-label','東京駅の地上から地下5階まで散策する3D階層モデル');$('viewport').append(renderer.domElement);camera=new THREE.PerspectiveCamera(65,innerWidth/innerHeight,.12,650);station=createBuildingScene(THREE);shoulderCamera=createShoulderCamera({camera,station});gateVisuals=addGateVisuals(station);applyQuality();setupInputs();setupUI();makeHotspots();setupMovementUI();setupFloorUI();setupGuideUI();applyFloor('1F');updateStats();setupGameEdition();window.addEventListener('resize',resize);window.addEventListener('pagehide',save);renderer.domElement.addEventListener('webglcontextlost',event=>{event.preventDefault();$('error-text').textContent='3D表示が中断されました。「もう一度開く」で散策を再開できます。';$('error').hidden=false});renderer.domElement.addEventListener('webglcontextrestored',()=>location.reload());frame(performance.now());$('loading').classList.add('loaded');setTimeout(()=>$('loading').hidden=true,700);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}catch(error){console.error('Station initialization failed',error);$('loading').hidden=true;$('error-text').textContent='3D表示を開始できませんでした。SafariやChromeの新しいバージョンで開き直してください。';$('error').hidden=false}}
init();
